-- stochastic-processes implementation for FokkerPlanck1D
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.Step(density,drift,diffusion,dx,dt)
    Num.Positive(dx,"grid spacing"); Num.Positive(dt,"time step"); Num.Nonnegative(diffusion,"diffusion coefficient")
    local stability=diffusion*dt/(dx*dx); assert(stability<=0.5,"explicit Fokker-Planck diffusion stability exceeded")
    local nextDensity=table.clone(density)
    for i=2,#density-1 do
        local driftFlux=(drift[i+1]*density[i+1]-drift[i-1]*density[i-1])/(2*dx)
        local diffusionTerm=(density[i+1]-2*density[i]+density[i-1])/(dx*dx)
        nextDensity[i]=density[i]+dt*(-driftFlux+diffusion*diffusionTerm)
    end
    for i=1,#nextDensity do assert(nextDensity[i]>=-1e-10,"negative probability density; reduce time step") end
    return nextDensity
end

return Module
